if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:e14cde6c9aac3e864c054708' and md5(to_jsonb(t)::text)='d48a6ccebd98bc0cbc47bdf42a1a31d2')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:e14cde6c9aac3e864c054708';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{rules,definition}',$native_a555d62b884809da${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:e14cde6c9aac3e864c054708","revision":2,"language":"es","name":"Set de ajedrez de dragón","aliases":[],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:abc8cc1fba54e1f5d353b9b712dea973ddb99a397e7369223b0ae1d6f83c2c4c","kind":"legacy","title":"Set de ajedrez de dragón","language":"es","rulesEdition":null,"locator":"official:equipment:es:e14cde6c9aac3e864c054708","verified":false},{"id":"original:8d65941aeb24bef131f9b456ecb3040d74efecd6459ac8d82f832bf765f920c0","kind":"legacy","title":"Set de ajedrez de dragón","language":"es","rulesEdition":null,"locator":"official:equipment:es:e14cde6c9aac3e864c054708","verified":false},{"id":"original:6536fbcb153d77ddb29f0128317fdcc4f1e3ff82787452441b51664449781aa9","kind":"legacy","title":"Dragonchess Set","language":"en","rulesEdition":null,"locator":"official:equipment:eng:caa56610bc3f032fccacce7a","verified":false},{"id":"original:a1c0aa715b1c6544171210f0ceb93f118475cbca1abdd442735c1cc8ecabfc4f","kind":"legacy","title":"Dragonchess Set","language":"en","rulesEdition":null,"locator":"official:equipment:eng:caa56610bc3f032fccacce7a","verified":false},{"id":"phb-supplied-equipment","kind":"book","title":"Manual del Jugador 2014 · documento español aportado por el GM","language":"es","rulesEdition":"2014","locator":"C:/Users/joaqu/Downloads/D&D - Manual del Jugador 5E (1).pdf · páginas PDF 128, 129","verified":true},{"id":"srd-5.1-es-tools-context","kind":"srd","title":"SRD 5.1 · herramientas, instrumentos y juegos · español oficial","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · páginas PDF 72–73 · CC BY 4.0","verified":true}],"category":"tool","subtypes":["gaming-set"],"magical":false,"rarity":"none","consumable":false,"properties":[],"weight":{"value":0.5,"unit":"lb"},"economy":{"basePrice":{"quantity":1,"unit":"gp"},"campaignPrice":null,"explanation":"Precio de la tabla Herramientas del manual aportado."},"description":[{"id":"game-row","section":"description","provenance":"reviewed-translation","sourceIds":["phb-supplied-equipment"],"type":"table","columns":["Objeto","Precio","Peso"],"rows":[["Set de ajedrez de dragón","1 po","½ lb."]]},{"id":"source-text","section":"rules","provenance":"reviewed-translation","sourceIds":["phb-supplied-equipment"],"type":"paragraph","text":"Set de Juego. Este objeto engloba un amplio rango de piezas de juego incluyendo dados y barajas de cartas (para juegos tales como Tres dragones). Unos pocos ejemplos comunes aparecen en la tabla Herramientas pero existen otro tipo de sets de juego. Si eres competente con un set de juego puedes añadir tu bonificador de competencia a las pruebas de característica que realices para jugar a un juego con este set. Cada tipo de set de juego requiere una competencia por separado."},{"id":"tools-context-general","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-tools-context"],"type":"paragraph","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza."},{"id":"tools-context-gaming","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-tools-context"],"type":"paragraph","text":"Juegos. Esta categoría de objetos incluye varios tipos de juegos de azar, normalmente basados en dados o cartas (como la Apuesta de los Tres Dragones). En la tabla “Herramientas” aparecen algunos ejemplos comunes, pero existen otros. Si eres competente con un juego, puedes sumar tu bonificador por competencia a las pruebas de característica que hagas para jugar con él. Cada tipo de juego requiere su propia competencia independiente."}],"requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"Equipo mundano; no requiere sintonización."},"weapon":null,"armor":null,"resources":[],"capabilities":[{"id":"mundane-assisted-use","name":"Jugar con competencia","activation":"other","trigger":"","requirements":{"attunement":false,"bearer":[],"presence":"possessed","explanation":"Equipo mundano; no requiere sintonización."},"target":"Portador","range":"","duration":"Según su uso.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"tool-check","kind":"tool-check","toolKey":"dragonchess-set","condition":""}],"execution":{"mode":"automatic","handler":"equipment-tool-check","explanation":"Prueba de herramienta con característica elegida, competencia, pericia y Talento Seguro cuando corresponden.","pendingAutomation":[]},"textBlockIds":["source-text"]}],"recoverySourceIds":["abc8cc1fba54e1f5d353b9b712dea973ddb99a397e7369223b0ae1d6f83c2c4c","8d65941aeb24bef131f9b456ecb3040d74efecd6459ac8d82f832bf765f920c0",