if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ef95f23bd99224f3cdf64a7d' and md5(to_jsonb(t)::text)='9c7141b016414e1d26e15f326f8e06a7')then raise exception 'NATIVE_DEFINITION_CHANGED:official:equipment:es:ef95f23bd99224f3cdf64a7d';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{rules,definition}',$native_6186fc07d4e8742d${"format":"equipment-definition-draft","schemaVersion":1,"id":"recovery:official:equipment:es:ef95f23bd99224f3cdf64a7d","revision":1,"language":"es","name":"Anillo de almacenamiento de conjuros","aliases":["Anillo de Almacenamiento de Hechizos","Ring of Spell Storing"],"baseDefinitionId":null,"origin":"official","sources":[{"id":"original:c23ec813fb2760a9ccc517481c21b2eb9de2709d62e0537ec270145b04351465","kind":"legacy","title":"Anillo de Almacenamiento de Hechizos","language":"es","rulesEdition":null,"locator":"official:equipment:es:ef95f23bd99224f3cdf64a7d","verified":false},{"id":"original:cf3f1539a6c6d60fc3993174118c6582a02c6630f9b8c19fe4aa97c8188e7262","kind":"legacy","title":"Anillo de Almacenamiento de Hechizos","language":"es","rulesEdition":null,"locator":"official:equipment:es:ef95f23bd99224f3cdf64a7d","verified":false},{"id":"original:71d9125e048514fc7a3dbba030e751b23a0e2fd49bcf47b8911ccd0f5715361f","kind":"legacy","title":"Ring of Spell Storing","language":"en","rulesEdition":null,"locator":"official:equipment:eng:f09fbdc41e6df6b4ab46adcf","verified":false},{"id":"original:dfc8b71ce1627b484ed5ca6ea625e945f7ef8e28a3c55a3fd3900933c8c5f30b","kind":"legacy","title":"Ring of Spell Storing","language":"en","rulesEdition":null,"locator":"official:equipment:eng:f09fbdc41e6df6b4ab46adcf","verified":false},{"id":"srd-5.1-es-equipment","kind":"srd","title":"Documento de referencia del sistema 5.1 · edición oficial española","language":"es","rulesEdition":"2014","locator":"https://media.wizards.com/2023/downloads/dnd/SRD_CC_v5.1_ES.pdf · página PDF 224 · CC-BY-4.0","verified":true},{"id":"srd-5.1-attribution","kind":"srd","title":"Atribución y licencia del SRD 5.1","language":"es","rulesEdition":"2014","locator":"Esta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es. Adaptaciones: separación de párrafos y tablas, datos estructurados y traducciones propias identificadas en cada bloque.","verified":true}],"category":"ring","subtypes":[],"magical":true,"rarity":"rare","consumable":false,"properties":["magic"],"weight":null,"economy":{"basePrice":null,"campaignPrice":null,"explanation":"La regla no fija precio de venta. Los precios antiguos y personalizaciones permanecen en sus originales; no se alteran tiendas ni copias."},"description":[{"id":"official-magic-0","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Este anillo almacena los conjuros que se lanzan sobre él y los conserva hasta que el portador sintonizado decida usarlos. El anillo puede guardar conjuros con un valor de hasta 5 niveles. Cuando lo encuentres, contendrá 1d6 − 1 niveles de conjuros almacenados, a elección de tu GM."},{"id":"official-magic-1","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Cualquier criatura puede lanzar un conjuro de niveles 1 a 5 sobre el anillo si lo toca mientras lanza el conjuro. El único efecto que tendrá el conjuro es que quedará almacenado en el anillo. Si el anillo no puede albergarlo, el conjuro se gastará sin efecto. El nivel del espacio utilizado para lanzar el conjuro determina cuánto espacio utiliza."},{"id":"official-magic-2","section":"rules","provenance":"official-spanish","sourceIds":["srd-5.1-es-equipment"],"type":"paragraph","text":"Mientras lleves puesto este anillo, podrás lanzar cualquiera de los conjuros almacenados. El conjuro utiliza el nivel del espacio, la CD de salvación de conjuros, el bonificador de ataque de conjuros y la aptitud mágica del lanzador original, pero, por lo demás, funciona como si tú lo hubieses lanzado. El conjuro lanzado desde el anillo deja de estar almacenado en él, por lo que deja espacio libre."}],"requirements":{"attunement":true,"bearer":[],"presence":"worn","explanation":"La sintonización y restricciones se aplican a los poderes mágicos, no a la mera posesión ni al uso mundano de un arma."},"weapon":null,"armor":null,"resources":[{"id":"almacenamiento","name":"almacenamiento","kind":"spell-storage","maximum":5,"unit":"niveles de conjuro","recovery":{"kind":"none"},"exhaustion":"No se puede activar sin el recurso necesario."}],"capabilities":[{"id":"store-spells","name":"Almacenar un conjuro","activation":"other","trigger":"","requirements":{"attunement":false,"bearer":[],"presence":"other","explanation":"No requiere sintonización."},"target":"El anillo, tocado al lanzar el conjuro","range":"","duration":"Hasta lanzar el conjuro almacenado.","concentration":false,"costs":[],"consumeQuantity":0,"effects":[{"id":"store-spells-0","condition":"","kind":"storage","resourceId":"almacenamiento","content":"spells","explanation":"Capacidad total de 5 niveles; cualquier criatura puede lanzar un conjuro de nivel 1 a 5 tocando el anillo, sin sintonizarse para cargarlo. El nivel del espacio gastado determina la capacidad ocupada. Si no cabe, el conjuro se gasta sin efecto. No hay recarga diaria ni se presume contenido a partir de cargas antiguas."}],"execution":{"mode":"automatic","handler":"equipment-spell-storage","explanation":"Almacenar y lanzar conjuros con sus estadísticas originales y su capacidad por niveles.","pendingAutomation":[]},"textBlockIds":["official-magic-0","official-magic-1","official-magic-2"]},{"id":"cast-stored-spell","name":"Lanzar un conjuro almacenado","activation":"other","trigger":"","requirements":{"attunement":true,"bearer":[],"presence":"worn","explanation":"La sintonización y restricciones se aplican a los poderes mágicos, no a la mera posesión ni al uso mundano de un arma."},"target":"Portador","range":"","duration":"Según el conjuro almacenado.","concentration":"spell-dependent","costs":[],"consumeQuantity":0,"effects":[{"id":"cast-stored-spell-0","condition":"","kind":"storage","resourceId":"almacenamiento","content":"spells","explanation":"Requiere llevar puesto y sintonizado el anillo. Conserva nivel del espacio, CD, bonificador de ataque y aptitud del lanzador original; por lo demás se trata como si el portador lo lanzase. Lanzarlo libera la capacidad que ocupaba. Debe resolverse la concentración del conjuro concreto."}],"execution":{"mode":"automatic","handler":"equipment-spell-storage","explanation":"Almacenar y lanzar conjuros con sus estadísticas originales y su capacidad por niveles.","pendingAutomation":[]},"textBlockIds":["official-magic-0","official-magic-1","official-magic-2"]}],"recoverySourceIds":["c23ec813fb2760a9ccc517481c21b2eb9de2709d62e0537ec270145b04351465","cf3f1539a6c6d60fc3993174118c6582a02c6630f9b8c19fe4aa97c8188e7262","71d9125e048514fc7a3dbba030e751b23a0e2fd49bcf47b8911ccd0f5715361f","dfc8b71ce1627b484ed5ca6ea625e945f7ef8e28a3c55a3fd3900933c8c5f30b"],"review":{"identity":true,"information":false,"editorial":true,"mechanics":true,"unresolved":["Cerrar la cobertura de los datos y diferencias antiguos antes de migrar o retirar versiones; las copias y precios comerciales siguen intactos."]}}$native_6186fc07d4e8742d$::jsonb,true),'{features}',$native_4548fbeea826434d$[{"id":"store-spells","kind":"other","name":"Almacenar un conjuro","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo almacena los conjuros que se lanzan sobre él y los conserva hasta que el portador sintonizado decida usarlos. El anillo puede guardar conjuros con un valor de hasta 5 niveles. Cuando lo encuentres, contendrá 1d6 − 1 niveles de conjuros almacenados, a elección de tu GM.\n\nCualquier criatura puede lanzar un conjuro de niveles 1 a 5 sobre el anillo si lo toca mientras lanza el conjuro. El único efecto que tendrá el conjuro es que quedará almacenado en el anillo. Si el anillo no puede albergarlo, el conjuro se gastará sin efecto. El nivel del espacio utilizado para lanzar el conjuro determina cuánto espacio utiliza.\n\nMientras lleves puesto este anillo, podrás lanzar cualquiera de los conjuros almacenados. El conjuro utiliza el nivel del espacio, la CD de salvación de conjuros, el bonificador de ataque de conjuros y la aptitud mágica del lanzador original, pero, por lo demás, funciona como si tú lo hubieses lanzado. El conjuro lanzado desde el anillo deja de estar almacenado en él, por lo que deja espacio libre.\n\nDuración: Hasta lanzar el conjuro almacenado..","showInActions":false},{"id":"cast-stored-spell","kind":"other","name":"Lanzar un conjuro almacenado","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este anillo almacena los conjuros que se lanzan sobre él y los conserva hasta que el portador sintonizado decida usarlos. El anillo puede guardar conjuros con un valor de hasta 5 niveles. Cuando lo encuentres, contendrá 1d6 − 1 niveles de conjuros almacenados, a elección de tu GM.\n\nCualquier criatura puede lanzar un conjuro de niveles 1 a 5 sobre el anillo si lo toca mientras lanza el conjuro. El único efecto que tendrá el conjuro es que quedará almacenado en el anillo. Si el anillo no puede albergarlo, el conjuro se gastará sin efecto. El nivel del espacio utilizado para lanzar el conjuro determina cuánto espacio utiliza.\n\nMientras lleves puesto este anillo, podrás lanzar cualquiera de los conjuros almacenados. El conjuro utiliza el nivel del espacio, la CD de salvación de conjuros, el bonificador de ataque de conjuros y la aptitud mágica del lanzador original, pero, por lo demás, funciona como si tú lo hubieses lanzado. El conjuro lanzado desde el anillo deja de estar almacenado en él, por lo que deja espacio libre.\n\nDuración: Según el conjuro almacenado..\n\nConcentración: según el conjuro.","showInActions":false}]$native_4548fbeea826434d$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ef95f23bd99224f3cdf64a7d';
